package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class BigMatrixImpl_operate_TriageGen0Test {

    @Test
    public void testOperate_Success() {
        // Setup a 2x3 matrix
        // [ 1, 2, 3 ]
        // [ 4, 5, 6 ]
        BigDecimal[][] data = {
            {new BigDecimal("1"), new BigDecimal("2"), new BigDecimal("3")},
            {new BigDecimal("4"), new BigDecimal("5"), new BigDecimal("6")}
        };
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        // Vector to multiply: [ 1, 0, 2 ]
        BigDecimal[] v = {
            new BigDecimal("1"),
            new BigDecimal("0"),
            new BigDecimal("2")
        };

        // Expected calculation:
        // row 0: (1*1) + (2*0) + (3*2) = 1 + 0 + 6 = 7
        // row 1: (4*1) + (5*0) + (6*2) = 4 + 0 + 12 = 16
        BigDecimal[] expected = {
            new BigDecimal("7"),
            new BigDecimal("16")
        };

        BigDecimal[] result = matrix.operate(v);

        assertArrayEquals(expected, result);
    }

    @Test
    public void testOperate_SingleElementMatrix() {
        // Setup a 1x1 matrix
        BigDecimal[][] data = {{new BigDecimal("5")}};
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        BigDecimal[] v = {new BigDecimal("2")};
        BigDecimal[] expected = {new BigDecimal("10")};

        BigDecimal[] result = matrix.operate(v);
        assertArrayEquals(expected, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testOperate_WrongLength_TooShort() {
        // Matrix is 2x2
        BigMatrixImpl matrix = new BigMatrixImpl(2, 2);
        // Vector is length 1
        BigDecimal[] v = {new BigDecimal("1")};

        matrix.operate(v);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testOperate_WrongLength_TooLong() {
        // Matrix is 2x2
        BigMatrixImpl matrix = new BigMatrixImpl(2, 2);
        // Vector is length 3
        BigDecimal[] v = {new BigDecimal("1"), new BigDecimal("2"), new BigDecimal("3")};

        matrix.operate(v);
    }

    @Test
    public void testOperate_WithZeroValues() {
        // Setup a 2x2 matrix with zeros
        BigDecimal[][] data = {
            {BigDecimal.ZERO, new BigDecimal("1")},
            {new BigDecimal("1"), BigDecimal.ZERO}
        };
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        BigDecimal[] v = {new BigDecimal("0"), new BigDecimal("0")};
        BigDecimal[] expected = {BigDecimal.ZERO, BigDecimal.ZERO};

        BigDecimal[] result = matrix.operate(v);

        // Using compareTo for BigDecimal to handle scale differences (0 vs 0.0)
        for (int i = 0; i < expected.length; i++) {
            assertEquals(0, expected[i].compareTo(result[i]));
        }
    }
}
